import { isOwnedFamily } from '../experimental/owned-family.ts'
import { finalizeOwnedScene } from './owned-data.ts'
import { createSceneWriteCapture, type SceneWriteReceipt } from './serialization.ts'
import { MAX_OCCLUSION_OPERATIONS } from './native-paint-emission.ts'
import { assertBackendConformance, isBuiltinDefaultBackend, isOriginalEnrolledDefaultBackend, getBackendDescriptor } from './backend.ts'
import { nativeDrawingOf, originalNativeDrawingOf, isOriginalSceneLowering, preferSceneDrawing, type DrawingProducer } from './drawing.ts'
import { drawNative, drawOriginalPositionedNative, type NativeDrawing } from './native-drawing.ts'
import type { FamilyLayoutResult } from '../agent/families.ts'
import type { ResolvedRenderRequest } from '../render-contract.ts'
import { resolvedFamilyRenderContextOf, resolvedRenderExecutionPlanOf } from '../render-contract.ts'
import { positionedForNativeProducer, positionedForSceneLowering, retainedFamilyProjection } from '../positioning.ts'
import { withTextMeasurementExecution } from '../text-measurement-profile.ts'
import { admitFamilyScene } from './admission.ts'
import { sceneAssertionsEnabled } from './assertions.ts'
import { withDeferredTerminalProjections } from './deferred-terminal-projection.ts'
import type { SceneDoc } from './ir.ts'
import { certifyNativePaint, certifyScenePaint, type PaintLayoutCertification } from './paint-certification.ts'
import { observeCache, observeFallback } from '../performance-observations.ts'
import { cachedNativeDrawing, retainNativeDrawing, type RetainedNativeDrawing } from '../experimental/position-cache.ts'

interface PositionedScene { scene: SceneDoc; crossChecks: boolean; writes?: SceneWriteReceipt; pendingWrites?: ReturnType<typeof createSceneWriteCapture>; certification?: PaintLayoutCertification }
type RenderableNativeDrawing = Pick<NativeDrawing, 'svg' | 'preparedText'>
type PositionedNative = { producer: DrawingProducer } & (
  { phase: 'captured'; drawing: NativeDrawing; evidence: NativeDrawing }
  | { phase: 'certified'; drawing: RenderableNativeDrawing; certification: PaintLayoutCertification }
)
const positionedWeakGet = WeakMap.prototype.get, positionedApply = Reflect.apply
const native = new WeakMap<FamilyLayoutResult, WeakMap<ResolvedRenderRequest, PositionedNative>>()
const retained = new WeakMap<FamilyLayoutResult, WeakMap<ResolvedRenderRequest, PositionedScene>>()
// Above this conservative native custody capacity, retain one immutable Scene
// before drawing. This avoids spending the paint allowance on an abandoned
// native capture; both adapters certify under the same unchanged limits.
const ER_NATIVE_PAINT_NODE_CAPACITY = 256

/** Resolve the transaction kind before the first Scene consumer. Verification
 * can inspect/certify before rendering; it must retain that same open receipt. */
export function actualPositionedSceneWriteEligible(request: ResolvedRenderRequest): boolean {
  const plan = resolvedRenderExecutionPlanOf(request)
  return plan.mode === 'scene' && !plan.family.id.startsWith('family:') && !!plan.backend
    && isBuiltinDefaultBackend(plan.backend.backend) && isOriginalEnrolledDefaultBackend(plan.backend.backend)
}

/** Lower once from the actual positioned artifact, shared by SVG, layout,
 * verification and receipt consumers. No source parse or layout is repeated. */
export function retainedPositionedScene(request: ResolvedRenderRequest, layout: FamilyLayoutResult): SceneDoc {
  let requests = retained.get(layout)
  if (!requests) { requests = new WeakMap(); retained.set(layout, requests) }
  const prior = requests.get(request)
  if (prior) {
    observeCache('positioned-scene', 'hit')
    if (sceneAssertionsEnabled(request) && !prior.crossChecks) {
      admitFamilyScene(resolvedRenderExecutionPlanOf(request).family, prior.scene, true)
      prior.crossChecks = true
    }
    return prior.scene
  }
  observeCache('positioned-scene', 'miss')
  const plan = resolvedRenderExecutionPlanOf(request)
  if (!plan.family.lowerScene) throw new Error(`Resolved ${request.output} family has no Scene lowering`)
  const colors = request.output === 'png' && request.appearance.colors.embedFontImport !== false
    ? { ...request.appearance.colors, embedFontImport: false } : request.appearance.colors
  const actualBackendWrite = actualPositionedSceneWriteEligible(request)
  const assertions = sceneAssertionsEnabled(request)
  const writer = plan.backend ?? (plan.mode === 'layout' && request.appearance.inferredBackend === 'default' ? getBackendDescriptor('default') : undefined)
  const writes = !plan.family.id.startsWith('family:') && writer && isBuiltinDefaultBackend(writer.backend) && isOriginalEnrolledDefaultBackend(writer.backend)
    ? createSceneWriteCapture(MAX_OCCLUSION_OPERATIONS, { fractionalCircleOutput: !request.appearance.styled && !request.appearance.colors.shadow, pageUnderlay: request.appearance.styled }, actualBackendWrite) : undefined
  const lower = () => {
    const scene = plan.family.lowerScene!({ positioned: positionedForSceneLowering(layout), colors, resolved: resolvedFamilyRenderContextOf(request) })
    // Actual-write proof requires its own defensive snapshot provenance.
    return !writes && isOwnedFamily(plan.family) && isOriginalSceneLowering(plan.family.lowerScene) ? finalizeOwnedScene(scene) : scene
  }
  const scene = withTextMeasurementExecution(plan.textMeasurement, () => admitFamilyScene(plan.family,
    !assertions && !plan.family.id.startsWith('family:') ? withDeferredTerminalProjections(lower) : lower(), assertions, writes?.observe))
  requests.set(request, { scene, crossChecks: assertions, ...(actualBackendWrite && writes ? { pendingWrites: writes, writes: writes.prepare(scene) } : { writes: writes?.finish(scene) }) })
  return scene
}

export function beginPositionedBackendEmission(request: ResolvedRenderRequest, layout: FamilyLayoutResult, context: object, proof: PaintLayoutCertification): boolean {
  const requests = positionedApply(positionedWeakGet, retained, [layout]) as WeakMap<ResolvedRenderRequest, PositionedScene> | undefined
  const entry = requests && positionedApply(positionedWeakGet, requests, [request]) as PositionedScene | undefined
  if (!entry?.pendingWrites) return false
  if (proof !== entry.certification) throw new Error('Scene proof belongs to a different positioned transaction')
  entry.pendingWrites.beginBackendEmission(entry.scene, context, proof)
  return true
}
export function finishPositionedBackendEmission(request: ResolvedRenderRequest, layout: FamilyLayoutResult, result: { kind: 'complete'; proof: PaintLayoutCertification } | { kind: 'abort' }): PaintLayoutCertification | undefined {
  const requests = positionedApply(positionedWeakGet, retained, [layout]) as WeakMap<ResolvedRenderRequest, PositionedScene> | undefined
  const entry = requests && positionedApply(positionedWeakGet, requests, [request]) as PositionedScene | undefined
  if (!entry?.pendingWrites) return undefined
  if (result.kind === 'abort') entry.pendingWrites.abortBackendEmission()
  else entry.certification = entry.pendingWrites.finishActual(result.proof)
  entry.pendingWrites = undefined
  return entry.certification
}

/** Native crisp work has no Scene document/group tree. Strong evidence and
 * alternate backends deliberately retain the extension-facing Scene adapter. */
export function retainedNativeDrawing(request: ResolvedRenderRequest, layout: FamilyLayoutResult): RenderableNativeDrawing | undefined {
  const plan = resolvedRenderExecutionPlanOf(request)
  // A completed async fallback selected the Scene consumer for this operand.
  // A later producer change cannot replace its proof with a new Native write.
  if (plan.consumer?.kind === 'scene-backend') return undefined
  // Once ER lowered a Scene, later observers cannot switch its actual operand.
  if (preferSceneDrawing(plan.family.id) && !native.get(layout)?.has(request) && retained.get(layout)?.has(request)) return undefined
  let bypass = sceneAssertionsEnabled(request) ? 'scene-assertions' : plan.family.id.startsWith('family:') ? 'external-family'
    : plan.consumer?.kind !== 'native-drawing' && plan.backend && !isBuiltinDefaultBackend(plan.backend.backend) ? 'alternate-backend'
      : !(plan.mode === 'layout' ? request.appearance.inferredBackend === 'default' : plan.mode === 'scene' && (plan.consumer?.kind === 'native-drawing' || plan.backend?.inputName === 'default')) ? 'unsupported-mode' : undefined
  if (!bypass && plan.family.id === 'er' && (retainedFamilyProjection(layout)?.nodes.length ?? 0) > ER_NATIVE_PAINT_NODE_CAPACITY) bypass = 'paint-proof-capacity'
  let producer = bypass ? undefined : nativeDrawingOf(plan.family.lowerScene)
  if (!bypass && preferSceneDrawing(plan.family.id) && producer && producer === originalNativeDrawingOf(plan.family.lowerScene)) bypass = 'owned-scene-geometry'
  if (!producer) bypass ??= 'no-native-producer'
  if (bypass) {
    observeCache('native-drawing', 'bypass', bypass)
    observeFallback('native-drawing', bypass)
    if (bypass !== 'owned-scene-geometry' || nativeDrawingOf(plan.family.lowerScene) === producer) return undefined
    // An observer installed a different producer before either capture began.
    producer = nativeDrawingOf(plan.family.lowerScene)
  }
  let requests = native.get(layout)
  if (!requests) { requests = new WeakMap(); native.set(layout, requests) }
  const prior = requests.get(request)
  if (prior) {
    observeCache('native-drawing', 'hit')
    if (prior.producer === nativeDrawingOf(plan.family.lowerScene)) return prior.drawing
    observeCache('native-drawing', 'bypass', 'changed-producer')
    requests.delete(request)
  }
  // The Scene SPI proves its broad backend contract. A selected Native
  // consumer instead proves the actual requested XML/paint write below.
  if (plan.backend) assertBackendConformance(plan.backend.conformance, plan.backend.inputName)
  // Positioning's ownership proof must still hold after layout observers run.
  // A changed producer executes on its detached graph and cannot publish a
  // drawing under the original producer's private cache entry.
  producer = nativeDrawingOf(plan.family.lowerScene)
  const cached = cachedNativeDrawing(request, layout, producer === originalNativeDrawingOf(plan.family.lowerScene))
  if (cached) {
    observeCache('native-drawing', 'hit', undefined, 'positioned-owner')
    const cachedProducer = producer
    if (cachedProducer && cachedProducer === nativeDrawingOf(plan.family.lowerScene) && cachedProducer === originalNativeDrawingOf(plan.family.lowerScene)) {
      requests.set(request, { phase: 'certified', drawing: cached, producer: cachedProducer, certification: cached.certification })
      return cached
    }
    // An observation callback changed the producer after the lookup. Revoke
    // this operation's proof and construct from the producer now installed.
    observeCache('native-drawing', 'bypass', 'changed-producer')
    cachedNativeDrawing(request, layout, false)
    producer = nativeDrawingOf(plan.family.lowerScene)
  }
  observeCache('native-drawing', 'miss')
  producer = nativeDrawingOf(plan.family.lowerScene)
  if (!producer) {
    observeCache('native-drawing', 'bypass', 'no-native-producer')
    observeFallback('native-drawing', 'no-native-producer')
    return undefined
  }
  const drawingProducer = producer
  const colors = request.output === 'png' && request.appearance.colors.embedFontImport !== false
    ? { ...request.appearance.colors, embedFontImport: false } : request.appearance.colors
  const drawing = withTextMeasurementExecution(plan.textMeasurement, () => drawOriginalPositionedNative(request, layout, drawingProducer) ?? drawNative(drawingProducer,
    { positioned: positionedForNativeProducer(layout, drawingProducer), colors, resolved: resolvedFamilyRenderContextOf(request) }, plan.family.id, request.appearance.styled ? request.appearance.style : undefined))
  requests.set(request, { phase: 'captured', drawing, producer: drawingProducer, evidence: drawing })
  return drawing
}

/** The receipt's layout certificate also records geometry drawn uncertified. */
function withGeometryCertification(certification: PaintLayoutCertification, layout: FamilyLayoutResult): PaintLayoutCertification {
  return layout.uncertifiedLayout ? Object.freeze({ ...certification, geometry: layout.uncertifiedLayout }) : certification
}

export function positionedPaintCertification(request: ResolvedRenderRequest, layout: FamilyLayoutResult): PaintLayoutCertification {
  const existing = native.get(layout)?.get(request)
  const drawing = existing?.drawing ?? retainedNativeDrawing(request, layout)
  if (drawing) {
    const requests = native.get(layout)!
    const entry = requests.get(request)!
    observeCache('paint-certification', entry.phase === 'certified' ? 'hit' : 'miss', undefined, 'native')
    if (entry.phase === 'certified') return entry.certification
    const evidence = entry.evidence
    const certification = withGeometryCertification(certifyNativePaint(evidence.header, evidence.paint, retainedFamilyProjection(layout), { outputSupported: !request.appearance.colors.shadow }), layout)
    const retained: RetainedNativeDrawing = Object.freeze({ svg: drawing.svg, preparedText: drawing.preparedText, certification })
    if (positionedApply(positionedWeakGet, requests, [request]) === entry) {
      requests.set(request, { phase: 'certified', drawing: retained, producer: entry.producer, certification })
    }
    const lower = resolvedRenderExecutionPlanOf(request).family.lowerScene
    if (entry.producer === nativeDrawingOf(lower) && entry.producer === originalNativeDrawingOf(lower)) retainNativeDrawing(request, layout, retained)
    else {
      observeCache('native-drawing', 'store-skipped', 'changed-producer')
      cachedNativeDrawing(request, layout, false)
    }
    return certification
  }
  const scene = retainedPositionedScene(request, layout)
  const entry = retained.get(layout)!.get(request)!
  observeCache('paint-certification', entry.certification ? 'hit' : 'miss', undefined, 'scene')
  if (entry.certification) return entry.certification
  const plan = resolvedRenderExecutionPlanOf(request)
  const supported = !request.appearance.colors.shadow && (plan.mode === 'layout' ? request.appearance.inferredBackend === 'default' : plan.mode === 'scene' && (plan.consumer?.kind === 'native-drawing' || plan.backend?.inputName === 'default'))
  const writer = plan.backend ?? (plan.mode === 'layout' && request.appearance.inferredBackend === 'default' ? getBackendDescriptor('default') : undefined)
  const written = supported && writer && isBuiltinDefaultBackend(writer.backend) && isOriginalEnrolledDefaultBackend(writer.backend)
  return entry.certification = withGeometryCertification(certifyScenePaint(scene, retainedFamilyProjection(layout), { outputSupported: supported, sceneWriteReceipt: written ? entry.writes : undefined }), layout)
}
