// ============================================================================
// Architecture structured body (BUILD-17: promotes architecture-beta from
// opaque-only fallback semantics to structured mutation, following the BUILD-15
// journey pilot).
//
// Modeled grammar (mirrors the legacy renderer parser, src/architecture/parser.ts):
//   title <Visible diagram heading>
//   group <id>(<icon>)[<Label>] [in <parentGroup>]
//   service <id>(<icon>)[<Label>] [in <group>]
//   junction <id> [in <group>]
//   <id>[{group}]:<SIDE> <arrow> <SIDE>:<id>[{group}]   (SIDE ∈ L|R|T|B)
//     arrows: -- --> <-- <-->  and labeled  -[label]-  forms
//   align row|column <id> <id> ...   (upstream v11.16.0 — shared shape parser
//     in src/architecture/align.ts; preserved and honored by layout)
//
// Structured-or-opaque: renderer-supported declarations, accTitle/accDescr and
// `{group}` endpoints are modeled when ids/icons have a portable spelling.
// Other source falls back losslessly to an opaque body.
// ============================================================================

import { unknownOpMessage } from './mutation-ops.ts'
import { serializeAlignDirective } from '../architecture/align.ts'
import type {
  ArchitectureBody, ArchitectureGroup, ArchitectureService, ArchitectureJunction,
  ArchitectureEdge, ArchitectureAlignment, ArchitectureSide, ArchitectureMutationOp,
  MutationError, Result, LayoutWarning, VerifyOptions,
} from './types.ts'
import { ok, err } from './types.ts'
import { labelOverflowCollector, setOptionalField } from './body-utils.ts'
import { appendAccessibilityLines } from './accessibility-envelope.ts'
import { resolveArchitectureIcon } from '../architecture/icons.ts'
import { parseAccessibilityDirective } from '../shared/accessibility-directives.ts'
import {
  readArchitectureStatements, architectureIconError, architectureIdError, architectureStatementEnds, architectureTerminalRejections, architectureTitle, architectureTitleSource, architectureIconTextSource,
} from '../architecture/parser.ts'
import { statementText } from '../shared/trailing-comment.ts'

// ---- Parser -----------------------------------------------------------------
// The statement shapes and Mermaid's id, icon and title terminals are the
// renderer parser's (src/architecture/parser.ts), so the surfaces cannot drift.

const SIDES = new Set<ArchitectureSide>(['L', 'R', 'T', 'B'])

function normalizeText(value: string): string {
  return value.split(/\r?\n/).map(part => part.trim()).filter(Boolean).join(' ')
}

/**
 * Parse architecture body lines (header excluded). Returns a structured body
 * only if EVERY non-blank, non-comment line is a modeled group, service,
 * junction, or edge, AND the diagram is internally consistent (no duplicate
 * ids, every `in` parent and every edge endpoint resolves). Otherwise returns
 * null (opaque fallback). Readable ids and icons without a portable spelling
 * also stay source-preserved so typed edits cannot regenerate rejected source.
 */
export function parseArchitectureBody(
  lines: string[],
  accessibility: import('./types.ts').Accessibility = {},
  rawBodyLines: string[] = lines,
): ArchitectureBody | null {
  let title: string | undefined
  let accessibilityTitle = accessibility.title
  let accessibilityDescription = accessibility.descr
  const groups: ArchitectureGroup[] = []
  const services: ArchitectureService[] = []
  const junctions: ArchitectureJunction[] = []
  const edges: ArchitectureEdge[] = []
  const alignments: ArchitectureAlignment[] = []
  const ids = new Set<string>()
  const groupIds = new Set<string>()
  const endpointIds = new Set<string>() // services + junctions (valid edge endpoints)

  for (const statement of readArchitectureStatements(rawBodyLines)) {
    if (statement.kind === 'invalid') return null
    if (statement.kind === 'blank' || statement.kind === 'comment') continue
    if (statement.kind === 'accessibility') {
      if (statement.directive.title) accessibilityTitle = statement.directive.value
      else accessibilityDescription = statement.directive.value
      continue
    }
    if (statement.kind === 'title') {
      if (title !== undefined) return null
      title = normalizeText(statement.value)
      if (!title) return null
      continue
    }

    if (statement.kind === 'group') {
      const declared = statement.declaration
      const { id, icon, parentId } = declared
      if (architectureIdError(id) || (icon && architectureIconError(icon))) return null
      if (ids.has(id) || (parentId && !groupIds.has(parentId))) return null
      ids.add(id)
      groupIds.add(id)
      const label = declared.title
      groups.push({ id, label, icon, parentId })
      continue
    }

    if (statement.kind === 'service') {
      const declared = statement.declaration
      const { id, icon, iconText, parentId } = declared
      if (architectureIdError(id) || (icon && architectureIconError(icon))) return null
      if (ids.has(id) || (parentId && !groupIds.has(parentId))) return null
      ids.add(id)
      endpointIds.add(id)
      const label = declared.title
      services.push({ id, label, icon, ...(iconText !== undefined ? { iconText } : {}), parentId })
      continue
    }

    if (statement.kind === 'junction') {
      const { id, parentId } = statement
      if (architectureIdError(id)) return null
      if (ids.has(id) || (parentId && !groupIds.has(parentId))) return null
      ids.add(id)
      endpointIds.add(id)
      junctions.push({ id, parentId })
      continue
    }

    // `align` is reserved upstream, so a leading `align` token is always a
    // directive. Malformed directives (bad axis, <2 members, duplicates) fall
    // back to opaque — the legacy render parser rejects them, exactly like
    // upstream, and verify reports the render failure honestly.
    if (statement.kind === 'align') {
      // Renderer semantics are declaration-order-sensitive: align can only
      // reference endpoints already declared at this source position.
      if (statement.alignment.members.some(member => !endpointIds.has(member))) return null
      alignments.push(statement.alignment)
      continue
    }

    if (statement.kind === 'edge') {
      const { edge } = statement
      if (!endpointIds.has(edge.source.id) || !endpointIds.has(edge.target.id)) return null
      const label = edge.label
      if (label && (label.includes('[') || label.includes(']'))) return null
      const endpoint = (value: typeof edge.source): ArchitectureEdge['source'] => ({ id: value.id, side: value.side, ...(value.boundary === 'group' ? { boundary: 'group' as const } : {}) })
      edges.push({ source: endpoint(edge.source), target: endpoint(edge.target), label, hasArrowStart: edge.hasArrowStart, hasArrowEnd: edge.hasArrowEnd })
      continue
    }

    // Unmodeled line (accTitle/accDescr/{group} boundary/anything else) → opaque.
    return null
  }

  // Validation: every `in` parent must be a declared group; every edge endpoint
  // and align member must be a declared service or junction. The legacy parser
  // rejects diagrams that violate these, so a structured body must satisfy
  // them to round-trip.
  for (const edge of edges) {
    if (!endpointIds.has(edge.source.id) || !endpointIds.has(edge.target.id)) return null
    for (const endpoint of [edge.source, edge.target]) {
      if (endpoint.boundary !== 'group') continue
      const service = services.find(candidate => candidate.id === endpoint.id)
      if (!service?.parentId) return null
    }
  }
  for (const alignment of alignments) {
    for (const member of alignment.members) {
      if (!endpointIds.has(member)) return null
    }
  }
  // A [title] ours reads but the writer cannot spell (a bare title ending in
  // a backslash, which the quoted form would read as an escaped quote) stays
  // source-preserved rather than a typed body that formats to other text.
  const titles = [...groups.map(group => group.label), ...services.map(service => service.label), ...edges.flatMap(edge => edge.label === undefined ? [] : [edge.label])]
  if (titles.some(label => architectureTitle(architectureTitleSource(label)) !== label)) return null

  return {
    kind: 'architecture',
    title,
    accessibilityTitle,
    accessibilityDescription,
    groups,
    services,
    junctions,
    edges,
    alignments,
  }
}

// ---- Serializer -------------------------------------------------------------

function renderNode(keyword: 'group' | 'service', id: string, label: string, icon?: string, parentId?: string, iconText?: string): string {
  const iconPart = iconText !== undefined ? ` ${architectureIconTextSource(iconText)} ` : icon ? `(${icon})` : ''
  const labelPart = `[${architectureTitleSource(label)}]`
  const inPart = parentId ? ` in ${parentId}` : ''
  return `  ${keyword} ${id}${iconPart}${labelPart}${inPart}`
}

function renderArrow(edge: ArchitectureEdge): string {
  if (edge.label !== undefined) {
    return `${edge.hasArrowStart ? '<' : ''}-[${architectureTitleSource(edge.label)}]-${edge.hasArrowEnd ? '>' : ''}`
  }
  if (edge.hasArrowStart && edge.hasArrowEnd) return '<-->'
  if (edge.hasArrowEnd) return '-->'
  if (edge.hasArrowStart) return '<--'
  return '--'
}

export function renderArchitecture(body: ArchitectureBody): string {
  const lines: string[] = ['architecture-beta']
  if (body.title !== undefined) lines.push(`  title ${body.title}`)
  appendAccessibilityLines(lines, body)
  for (const g of body.groups) lines.push(renderNode('group', g.id, g.label, g.icon, g.parentId))
  for (const s of body.services) lines.push(renderNode('service', s.id, s.label, s.icon, s.parentId, s.iconText))
  for (const j of body.junctions) {
    lines.push(`  junction ${j.id}${j.parentId ? ` in ${j.parentId}` : ''}`)
  }
  for (const e of body.edges) lines.push(`  ${architectureEdgeSource(e)}`)
  // Align directives last: canonical order guarantees every member is already
  // declared, which both the upstream grammar and the legacy parser require.
  for (const a of body.alignments ?? []) {
    lines.push(`  ${serializeAlignDirective(a)}`)
  }
  return lines.join('\n') + '\n'
}

// ---- Mutator ----------------------------------------------------------------

function cloneArchitecture(b: ArchitectureBody): ArchitectureBody {
  return {
    kind: 'architecture',
    title: b.title,
    accessibilityTitle: b.accessibilityTitle,
    accessibilityDescription: b.accessibilityDescription,
    groups: b.groups.map(g => ({ ...g })),
    services: b.services.map(s => ({ ...s })),
    junctions: b.junctions.map(j => ({ ...j })),
    edges: b.edges.map(e => ({
      source: { ...e.source }, target: { ...e.target },
      label: e.label, hasArrowStart: e.hasArrowStart, hasArrowEnd: e.hasArrowEnd,
    })),
    ...(b.alignments ? { alignments: b.alignments.map(a => ({ axis: a.axis, members: [...a.members] })) } : {}),
  }
}

/**
 * Keep align directives coherent after id changes: drop removed members and
 * dissolve any directive left with fewer than two (the grammar's floor —
 * mirrors the edge cascade in remove_service). `rename` rewrites in place.
 */
function dropAlignmentMember(next: ArchitectureBody, id: string): void {
  if (!next.alignments) return
  next.alignments = next.alignments
    .map(a => ({ axis: a.axis, members: a.members.filter(m => m !== id) }))
    .filter(a => a.members.length >= 2)
}

function renameAlignmentMember(next: ArchitectureBody, from: string, to: string): void {
  if (!next.alignments) return
  for (const a of next.alignments) {
    a.members = a.members.map(m => (m === from ? to : m))
  }
}

function allIds(b: ArchitectureBody): Set<string> {
  const s = new Set<string>()
  for (const g of b.groups) s.add(g.id)
  for (const sv of b.services) s.add(sv.id)
  for (const j of b.junctions) s.add(j.id)
  return s
}

function validId(value: unknown, field: string): Result<string, MutationError> {
  const error = typeof value === 'string' ? architectureIdError(value) : undefined
  if (typeof value !== 'string' || error) {
    return err({ code: 'INVALID_OP', message: error?.message ?? `Architecture ${field} must be a string, got ${JSON.stringify(value)}` })
  }
  return ok(value)
}

/** An icon name Mermaid's lexer reads, or undefined for none. */
function validIcon(value: unknown, field: string): Result<string | undefined, MutationError> {
  if (value === undefined || value === null) return ok(undefined)
  const icon = typeof value === 'string' ? value.trim() : undefined
  if (icon === undefined || (icon !== '' && architectureIconError(icon))) {
    return err({ code: 'INVALID_OP', message: `Architecture ${field} must be letters, digits, _, - and :, got ${JSON.stringify(value)}` })
  }
  return ok(icon || undefined)
}

function normalizeLabel(value: string, field: string): Result<string, MutationError> {
  if (typeof value !== 'string') return err({ code: 'INVALID_OP', message: `Architecture ${field} must be a string` })
  const normalized = value.trim()
  // Labels are rendered inside [...]; a bracket would break round-trip.
  if (!normalized || normalized.includes('[') || normalized.includes(']')) {
    return err({ code: 'INVALID_OP', message: `Architecture ${field} must be non-empty and must not contain [ or ]` })
  }
  // A label that is not words and spaces is written quoted, where Mermaid
  // reads a backslash as an escape.
  if (normalized.includes('\\')) {
    return err({ code: 'INVALID_OP', message: `Architecture ${field} must not contain a backslash` })
  }
  return ok(normalized)
}

function validSide(value: unknown): value is ArchitectureSide {
  return typeof value === 'string' && SIDES.has(value as ArchitectureSide)
}

function normalizeAccessibilityText(value: unknown, field: string, multiline: boolean): Result<string, MutationError> {
  if (typeof value !== 'string') return err({ code: 'INVALID_OP', message: `Architecture ${field} must be a string or null` })
  const normalized = multiline
    ? value.split(/\r?\n/).map(line => line.trim()).filter(Boolean).join('\n')
    : normalizeText(value)
  if (!normalized || normalized.includes('}')) {
    return err({ code: 'INVALID_OP', message: `Architecture ${field} must be non-empty and must not contain }` })
  }
  return ok(normalized)
}

function validateArchitectureEndpoint(
  body: ArchitectureBody,
  id: string,
  boundary: 'item' | 'group' | undefined,
): Result<void, MutationError> {
  const service = body.services.find(candidate => candidate.id === id)
  const junction = body.junctions.find(candidate => candidate.id === id)
  if (!service && !junction) return err({ code: 'SERVICE_NOT_FOUND', message: `No service/junction "${id}"` })
  if (boundary === 'group' && !service?.parentId) {
    return err({
      code: 'INVALID_OP',
      message: service
        ? `Service "${id}" is not inside a group, so boundary "group" is invalid`
        : `Architecture group boundaries apply only to services; "${id}" is a junction`,
    })
  }
  return ok(undefined)
}

/** An edge as its Mermaid statement writes it. */
function architectureEdgeSource(e: ArchitectureEdge): string {
  const boundary = (endpoint: ArchitectureEdge['source']) => endpoint.boundary === 'group' ? '{group}' : ''
  return `${e.source.id}${boundary(e.source)}:${e.source.side} ${renderArrow(e)} ${e.target.side}:${e.target.id}${boundary(e.target)}`
}

/**
 * A `{group}` endpoint attaches to its service's group boundary, so it must
 * lead out of that group: the other end may not sit inside it (directly or in
 * a nested group), nor attach to the same or a nested group's boundary. Such
 * an edge has no route that crosses the boundary it names. Pinned Mermaid
 * rejects the case where both ends share their direct group.
 */
function architectureGroupEdgeConflict(body: ArchitectureBody, e: ArchitectureEdge): { group: string; other: string; mermaidRejects: boolean } | undefined {
  const parentOf = (id: string) => body.services.find(item => item.id === id)?.parentId ?? body.junctions.find(item => item.id === id)?.parentId
  const within = (groupId: string | undefined, ancestor: string): boolean => {
    for (let current = groupId, depth = 0; current !== undefined && depth <= body.groups.length; current = body.groups.find(group => group.id === current)?.parentId, depth++) {
      if (current === ancestor) return true
    }
    return false
  }
  for (const [end, other] of [[e.source, e.target], [e.target, e.source]] as const) {
    const group = end.boundary === 'group' ? parentOf(end.id) : undefined
    if (group === undefined || !within(parentOf(other.id), group)) continue
    const endParent = parentOf(end.id), otherParent = parentOf(other.id)
    return { group, other: other.id, mermaidRejects: endParent !== undefined && endParent === otherParent }
  }
  return undefined
}

/** Edge id convention: `<from>-><to>` (matches the flowchart edgeId idiom). */
export function architectureEdgeId(e: ArchitectureEdge): string {
  return `${e.source.id}->${e.target.id}`
}

export function mutateArchitecture(body: ArchitectureBody, op: ArchitectureMutationOp): Result<ArchitectureBody, MutationError> {
  const result = applyArchitectureOp(body, op)
  if (!result.ok) return result
  // Edits never write a `{group}` edge that cannot leave its group (Mermaid
  // rejects the same-group case); one already in the source stays reported.
  const before = new Set(body.edges.filter(edge => architectureGroupEdgeConflict(body, edge)).map(architectureEdgeSource))
  for (const edge of result.value.edges) {
    const conflict = architectureGroupEdgeConflict(result.value, edge)
    if (!conflict || before.has(architectureEdgeSource(edge))) continue
    return err({
      code: 'INVALID_OP',
      message: `Edge "${architectureEdgeSource(edge)}" would join group "${conflict.group}" to "${conflict.other}", which is inside it; a {group} endpoint must lead out of its group. Set that endpoint's boundary to "item" (update_edge) or keep "${conflict.other}" outside "${conflict.group}".`,
    })
  }
  return result
}

function applyArchitectureOp(body: ArchitectureBody, op: ArchitectureMutationOp): Result<ArchitectureBody, MutationError> {
  const next = cloneArchitecture(body)

  switch (op.kind) {
    case 'set_title': {
      if (op.title === null) {
        next.title = undefined
      } else {
        const title = normalizeText(op.title)
        if (!title) return err({ code: 'INVALID_OP', message: 'Architecture title must be a non-empty string or null' })
        next.title = title
      }
      break
    }
    case 'set_accessibility_title': {
      const title = setOptionalField(next, 'accessibilityTitle', op.title, value => normalizeAccessibilityText(value, 'accessibility title', false))
      if (!title.ok) return title
      break
    }
    case 'set_accessibility_description': {
      const description = setOptionalField(next, 'accessibilityDescription', op.description, value => normalizeAccessibilityText(value, 'accessibility description', true))
      if (!description.ok) return description
      break
    }
    case 'add_service': {
      const id = validId(op.id, 'service id')
      if (!id.ok) return id
      if (allIds(next).has(id.value)) return err({ code: 'INVALID_OP', message: `Identifier "${id.value}" already exists` })
      const label = normalizeLabel(op.label ?? id.value, 'service label')
      if (!label.ok) return label
      const validatedIcon = validIcon(op.icon, 'service icon')
      if (!validatedIcon.ok) return validatedIcon
      const icon = validatedIcon.value
      if (op.iconText !== undefined && op.iconText !== null && typeof op.iconText !== 'string') return err({ code: 'INVALID_OP', message: 'Architecture iconText must be a string or null' })
      const iconText = op.iconText ?? undefined
      if (icon && iconText !== undefined) return err({ code: 'INVALID_OP', message: 'Choose an Architecture icon name or iconText, not both' })
      if (op.group !== undefined && op.group !== null) {
        const g = validId(op.group, 'group id')
        if (!g.ok) return g
        if (!next.groups.some(grp => grp.id === g.value)) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${g.value}"` })
        next.services.push({ id: id.value, label: label.value, icon, ...(iconText !== undefined ? { iconText } : {}), parentId: g.value })
      } else {
        next.services.push({ id: id.value, label: label.value, icon, ...(iconText !== undefined ? { iconText } : {}) })
      }
      break
    }
    case 'remove_service': {
      const idx = next.services.findIndex(s => s.id === op.id)
      if (idx < 0) return err({ code: 'SERVICE_NOT_FOUND', message: `No service "${op.id}"` })
      next.services.splice(idx, 1)
      // Cascade: drop every edge that touches the removed service, and every
      // align membership (dissolving directives that fall below two members).
      next.edges = next.edges.filter(e => e.source.id !== op.id && e.target.id !== op.id)
      dropAlignmentMember(next, op.id)
      break
    }
    case 'rename_service': {
      const from = validId(op.from, 'service id')
      if (!from.ok) return from
      const to = validId(op.to, 'service id')
      if (!to.ok) return to
      const svc = next.services.find(s => s.id === from.value)
      if (!svc) return err({ code: 'SERVICE_NOT_FOUND', message: `No service "${from.value}"` })
      if (from.value !== to.value && allIds(next).has(to.value)) {
        return err({ code: 'INVALID_OP', message: `Identifier "${to.value}" already exists` })
      }
      svc.id = to.value
      // Keep edges and align memberships anchored to the renamed service.
      for (const e of next.edges) {
        if (e.source.id === from.value) e.source.id = to.value
        if (e.target.id === from.value) e.target.id = to.value
      }
      renameAlignmentMember(next, from.value, to.value)
      break
    }
    case 'set_service_label': {
      const svc = next.services.find(s => s.id === op.id)
      if (!svc) return err({ code: 'SERVICE_NOT_FOUND', message: `No service "${op.id}"` })
      const label = normalizeLabel(op.label, 'service label')
      if (!label.ok) return label
      svc.label = label.value
      break
    }
    case 'set_service_icon': {
      const svc = next.services.find(s => s.id === op.id)
      if (!svc) return err({ code: 'SERVICE_NOT_FOUND', message: `No service "${op.id}"` })
      if (op.icon === null) { delete svc.icon; delete svc.iconText; break }
      const icon = validIcon(op.icon, 'service icon')
      if (!icon.ok) return icon
      if (!icon.value) return err({ code: 'INVALID_OP', message: 'Architecture service icon must be non-empty (use null to clear)' })
      svc.icon = icon.value
      delete svc.iconText
      break
    }
    case 'set_service_icon_text': {
      const svc = next.services.find(s => s.id === op.id)
      if (!svc) return err({ code: 'SERVICE_NOT_FOUND', message: `No service "${op.id}"` })
      if (op.text === null) { delete svc.iconText; break }
      if (typeof op.text !== 'string') return err({ code: 'INVALID_OP', message: 'Architecture icon text must be a string or null' })
      svc.iconText = op.text
      delete svc.icon
      break
    }
    case 'move_service': {
      const svc = next.services.find(s => s.id === op.id)
      if (!svc) return err({ code: 'SERVICE_NOT_FOUND', message: `No service "${op.id}"` })
      if (op.group === null) {
        const boundaryEdge = next.edges.find(edge =>
          (edge.source.id === op.id && edge.source.boundary === 'group')
            || (edge.target.id === op.id && edge.target.boundary === 'group'))
        if (boundaryEdge) {
          return err({
            code: 'INVALID_OP',
            message: `Service "${op.id}" has a group-boundary edge; update the edge boundary to "item" before moving it to root`,
          })
        }
        delete svc.parentId
        break
      }
      const g = validId(op.group, 'group id')
      if (!g.ok) return g
      if (!next.groups.some(grp => grp.id === g.value)) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${g.value}"` })
      svc.parentId = g.value
      break
    }
    case 'add_junction': {
      const id = validId(op.id, 'junction id')
      if (!id.ok) return id
      if (allIds(next).has(id.value)) return err({ code: 'INVALID_OP', message: `Identifier "${id.value}" already exists` })
      let parentId: string | undefined
      if (op.group !== undefined && op.group !== null) {
        const group = validId(op.group, 'group id')
        if (!group.ok) return group
        if (!next.groups.some(candidate => candidate.id === group.value)) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${group.value}"` })
        parentId = group.value
      }
      next.junctions.push({ id: id.value, parentId })
      break
    }
    case 'remove_junction': {
      const index = next.junctions.findIndex(junction => junction.id === op.id)
      if (index < 0) return err({ code: 'SERVICE_NOT_FOUND', message: `No junction "${op.id}"` })
      next.junctions.splice(index, 1)
      next.edges = next.edges.filter(edge => edge.source.id !== op.id && edge.target.id !== op.id)
      dropAlignmentMember(next, op.id)
      break
    }
    case 'rename_junction': {
      const from = validId(op.from, 'junction id')
      if (!from.ok) return from
      const to = validId(op.to, 'junction id')
      if (!to.ok) return to
      const junction = next.junctions.find(candidate => candidate.id === from.value)
      if (!junction) return err({ code: 'SERVICE_NOT_FOUND', message: `No junction "${from.value}"` })
      if (from.value !== to.value && allIds(next).has(to.value)) return err({ code: 'INVALID_OP', message: `Identifier "${to.value}" already exists` })
      junction.id = to.value
      for (const edge of next.edges) {
        if (edge.source.id === from.value) edge.source.id = to.value
        if (edge.target.id === from.value) edge.target.id = to.value
      }
      renameAlignmentMember(next, from.value, to.value)
      break
    }
    case 'move_junction': {
      const junction = next.junctions.find(candidate => candidate.id === op.id)
      if (!junction) return err({ code: 'SERVICE_NOT_FOUND', message: `No junction "${op.id}"` })
      if (op.group === null) { delete junction.parentId; break }
      const group = validId(op.group, 'group id')
      if (!group.ok) return group
      if (!next.groups.some(candidate => candidate.id === group.value)) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${group.value}"` })
      junction.parentId = group.value
      break
    }
    case 'add_group': {
      const id = validId(op.id, 'group id')
      if (!id.ok) return id
      if (allIds(next).has(id.value)) return err({ code: 'INVALID_OP', message: `Identifier "${id.value}" already exists` })
      const label = normalizeLabel(op.label ?? id.value, 'group label')
      if (!label.ok) return label
      const validatedIcon = validIcon(op.icon, 'group icon')
      if (!validatedIcon.ok) return validatedIcon
      const icon = validatedIcon.value
      let parentId: string | undefined
      if (op.parent !== undefined && op.parent !== null) {
        const p = validId(op.parent, 'group id')
        if (!p.ok) return p
        if (!next.groups.some(grp => grp.id === p.value)) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${p.value}"` })
        parentId = p.value
      }
      next.groups.push({ id: id.value, label: label.value, icon, parentId })
      break
    }
    case 'set_group_label': {
      const group = next.groups.find(candidate => candidate.id === op.id)
      if (!group) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${op.id}"` })
      const label = normalizeLabel(op.label, 'group label')
      if (!label.ok) return label
      group.label = label.value
      break
    }
    case 'remove_group': {
      const idx = next.groups.findIndex(g => g.id === op.id)
      if (idx < 0) return err({ code: 'GROUP_NOT_FOUND', message: `No group "${op.id}"` })
      // Policy: refuse to remove a non-empty group. Removing a group that still
      // owns services, junctions, or child groups would orphan members (the
      // legacy parser requires every `in <group>` to resolve), so we make the
      // caller move/remove members first rather than silently re-parenting or
      // cascade-deleting an entire subtree. Tested in agent-architecture.test.ts.
      const hasMembers =
        next.services.some(s => s.parentId === op.id) ||
        next.junctions.some(j => j.parentId === op.id) ||
        next.groups.some(g => g.parentId === op.id)
      if (hasMembers) return err({ code: 'INVALID_OP', message: `Group "${op.id}" is not empty; move or remove its members first` })
      next.groups.splice(idx, 1)
      break
    }
    case 'add_edge': {
      const from = validId(op.from, 'service id')
      if (!from.ok) return from
      const to = validId(op.to, 'service id')
      if (!to.ok) return to
      if (!validSide(op.fromSide)) return err({ code: 'INVALID_OP', message: `fromSide must be one of L|R|T|B, got ${JSON.stringify(op.fromSide)}` })
      if (!validSide(op.toSide)) return err({ code: 'INVALID_OP', message: `toSide must be one of L|R|T|B, got ${JSON.stringify(op.toSide)}` })
      const fromBoundary = op.fromBoundary ?? 'item'
      const toBoundary = op.toBoundary ?? 'item'
      const sourceValid = validateArchitectureEndpoint(next, from.value, fromBoundary)
      if (!sourceValid.ok) return sourceValid
      const targetValid = validateArchitectureEndpoint(next, to.value, toBoundary)
      if (!targetValid.ok) return targetValid
      let label: string | undefined
      if (op.label !== undefined && op.label !== null) {
        const l = normalizeLabel(op.label, 'edge label')
        if (!l.ok) return l
        label = l.value
      }
      next.edges.push({
        source: { id: from.value, side: op.fromSide, ...(fromBoundary === 'group' ? { boundary: 'group' as const } : {}) },
        target: { id: to.value, side: op.toSide, ...(toBoundary === 'group' ? { boundary: 'group' as const } : {}) },
        label,
        hasArrowStart: op.hasArrowStart ?? false,
        hasArrowEnd: op.hasArrowEnd ?? true,
      })
      break
    }
    case 'update_edge': {
      if (!Number.isInteger(op.index) || op.index < 0 || !next.edges[op.index]) {
        return err({ code: 'EDGE_NOT_FOUND', message: `No edge at index ${op.index}` })
      }
      const edge = next.edges[op.index]!
      if (op.from !== undefined) {
        const from = validId(op.from, 'service id')
        if (!from.ok) return from
        edge.source.id = from.value
      }
      if (op.to !== undefined) {
        const to = validId(op.to, 'service id')
        if (!to.ok) return to
        edge.target.id = to.value
      }
      if (op.fromSide !== undefined) {
        if (!validSide(op.fromSide)) return err({ code: 'INVALID_OP', message: `fromSide must be one of L|R|T|B, got ${JSON.stringify(op.fromSide)}` })
        edge.source.side = op.fromSide
      }
      if (op.toSide !== undefined) {
        if (!validSide(op.toSide)) return err({ code: 'INVALID_OP', message: `toSide must be one of L|R|T|B, got ${JSON.stringify(op.toSide)}` })
        edge.target.side = op.toSide
      }
      if (op.fromBoundary !== undefined) {
        if (op.fromBoundary === 'group') edge.source.boundary = 'group'
        else delete edge.source.boundary
      }
      if (op.toBoundary !== undefined) {
        if (op.toBoundary === 'group') edge.target.boundary = 'group'
        else delete edge.target.boundary
      }
      const sourceValid = validateArchitectureEndpoint(next, edge.source.id, edge.source.boundary)
      if (!sourceValid.ok) return sourceValid
      const targetValid = validateArchitectureEndpoint(next, edge.target.id, edge.target.boundary)
      if (!targetValid.ok) return targetValid
      if ('label' in op) {
        if (op.label === null || op.label === undefined) delete edge.label
        else {
          const label = normalizeLabel(op.label, 'edge label')
          if (!label.ok) return label
          edge.label = label.value
        }
      }
      if (op.hasArrowStart !== undefined) edge.hasArrowStart = op.hasArrowStart
      if (op.hasArrowEnd !== undefined) edge.hasArrowEnd = op.hasArrowEnd
      break
    }
    case 'remove_edge': {
      if (typeof op.index === 'number') {
        if (!next.edges[op.index]) return err({ code: 'EDGE_NOT_FOUND', message: `No edge at index ${op.index}` })
        next.edges.splice(op.index, 1)
      } else if (typeof op.id === 'string') {
        const idx = next.edges.findIndex(e => architectureEdgeId(e) === op.id)
        if (idx < 0) return err({ code: 'EDGE_NOT_FOUND', message: `No edge "${op.id}"` })
        next.edges.splice(idx, 1)
      } else {
        return err({ code: 'INVALID_OP', message: 'remove_edge requires index (number) or id (from->to)' })
      }
      break
    }
    default: {
      const _x: never = op
      return err({ code: 'INVALID_OP', message: unknownOpMessage('architecture', _x) })
    }
  }


  return ok(next)
}

// ---- Verifier (FamilyDescriptor.verify hook) --------------------------------

const NATIVE_ARCHITECTURE_ICONS = new Set(['cloud', 'database', 'disk', 'internet', 'server'])

function unknownArchitectureIcon(target: string, icon?: string): LayoutWarning | null {
  return icon && !NATIVE_ARCHITECTURE_ICONS.has(icon.trim().toLowerCase()) && resolveArchitectureIcon(icon) === null
    ? { code: 'UNKNOWN_SHAPE', node: target, shape: `architecture-icon:${icon}` }
    : null
}

const ARCHITECTURE_PORTABLE_FORM = {
  id: 'avoid architecture keywords and prefixes L, R, T, B or title, and keep dashes only inside the id',
  icon: 'name an icon with letters, digits, _, - and : only',
  title: 'put the whole title in double quotes',
} as const

/** Architecture source ours reads where pinned Mermaid rejects it, each on its
 * canonical line: an id, (icon) or [title] outside Mermaid's lexer terminal is
 * read as written. */
export function architectureUnsupportedSyntaxWarnings(canonicalSource: string): LayoutWarning[] {
  const lines = canonicalSource.split(/\r?\n/)
  const header = lines.findIndex(line => /^architecture(?:-beta)?\b/i.test(line.trim()))
  if (header < 0) return []
  const warnings: LayoutWarning[] = []
  const ends = architectureStatementEnds(lines)
  for (let index = header + 1; index < lines.length; index++) {
    const directive = parseAccessibilityDirective(lines, index)
    if (directive === undefined) break
    if (directive !== null) {
      index = directive.endIndex
      continue
    }
    const start = index
    index = ends[index]!
    for (const { terminal, what } of architectureTerminalRejections(statementText(lines, start, index))) {
      warnings.push({
        code: 'UNSUPPORTED_SYNTAX',
        syntax: `architecture_${terminal}`,
        line: start + 1,
        message: `${what}. Pinned Mermaid rejects this; ${ARCHITECTURE_PORTABLE_FORM[terminal]}.`,
      })
    }
  }
  return warnings
}

/** Source-level diagnostic used when otherwise-renderable architecture syntax
 * falls back to an opaque body. Verification must not lose icon safety merely
 * because a different line was outside the structured subset. */
export function verifyOpaqueArchitectureIcons(source: string): LayoutWarning[] {
  const warnings: LayoutWarning[] = []
  for (const line of source.split(/\r?\n/)) {
    const match = line.trim().match(/^(?:service|group)\s+([A-Za-z_][\w-]*)\s*\(([^)]+)\)/i)
    if (!match) continue
    const warning = unknownArchitectureIcon(match[1]!, match[2]!.trim())
    if (warning) warnings.push(warning)
  }
  return warnings
}

export function verifyArchitecture(body: ArchitectureBody, opts: VerifyOptions): LayoutWarning[] {
  const warnings: LayoutWarning[] = []
  const overflow = labelOverflowCollector(warnings, opts)
  if (body.groups.length === 0 && body.services.length === 0 && body.junctions.length === 0
    && body.title === undefined && body.accessibilityTitle === undefined && body.accessibilityDescription === undefined) {
    warnings.push({ code: 'EMPTY_DIAGRAM' })
  }
  if (body.title !== undefined) overflow('title', body.title)
  if (body.accessibilityTitle !== undefined) overflow('accessibility-title', body.accessibilityTitle)
  if (body.accessibilityDescription !== undefined) overflow('accessibility-description', body.accessibilityDescription)
  const checkIcon = (target: string, icon?: string): void => {
    const warning = unknownArchitectureIcon(target, icon)
    if (warning) warnings.push(warning)
  }
  for (const g of body.groups) { overflow(g.id, g.label); checkIcon(g.id, g.icon) }
  for (const s of body.services) { overflow(s.id, s.label); checkIcon(s.id, s.icon) }
  body.edges.forEach((e, i) => {
    // Anchor any edge whose endpoints no longer resolve (defensive; mutate keeps
    // these consistent, but an externally-synthesized body might not).
    const ids = new Set([...body.services.map(s => s.id), ...body.junctions.map(j => j.id)])
    if (!ids.has(e.source.id) || !ids.has(e.target.id)) {
      warnings.push({
        code: 'EDGE_MISANCHORED', edge: `edge#${i}:${architectureEdgeId(e)}`,
        from: ids.has(e.source.id) ? e.source.id : undefined,
        to: ids.has(e.target.id) ? e.target.id : undefined,
      })
    }
    if (e.label !== undefined) overflow(`edge#${i}:${architectureEdgeId(e)}`, e.label)
    const conflict = ids.has(e.source.id) && ids.has(e.target.id) ? architectureGroupEdgeConflict(body, e) : undefined
    if (conflict) {
      warnings.push({
        code: 'UNSUPPORTED_SYNTAX', syntax: 'architecture_group_edge_inside_group',
        message: `Edge ${i} "${architectureEdgeSource(e)}" joins group "${conflict.group}" to "${conflict.other}", which is inside it, so no route can cross the boundary it names and the drawing misleads.${conflict.mermaidRejects ? ' Pinned Mermaid rejects this edge.' : ''} Use an item endpoint, or move "${conflict.other}" outside "${conflict.group}".`,
      })
    }
  })
  return warnings
}
